/bin/bash -lc "mkdir -p api-docs && python - <<'PY'
import urllib.request,re,html
from pathlib import Path
urls={
'Dynamics':'https://brainpy.readthedocs.io/apis/generated/brainpy.state.Dynamics.html',
'DeltaProj':'https://brainpy.readthedocs.io/apis/generated/brainpy.state.DeltaProj.html',
'poisson':'https://brainstate.readthedocs.io/apis/generated/brainstate.random.poisson.html',
}
for name,url in urls.items():
 try:
  raw=urllib.request.urlopen(url,timeout=30).read().decode()
  section=raw[raw.find('<section id='):raw.find('<"'!-- /main -->'"')]
  text=html.unescape(re.sub('<["'^>]+>'"',' ',section))
  text=re.sub(r'\\s+',' ',text)
  Path('api-docs/'+name+'.txt').write_text(url+'\\n'+text)
  if name=='Dynamics':
   for word in ['class brainpy','sum_delta_inputs','add_delta_input','size']:
    pos=text.find(word); print(name,word,text[max(0,pos-100):pos+1300])
  else: print(name,text[:9000])
 except Exception as e: print(name,type(e).__name__,str(e))
PY"

